<template>
  <section class="meeting-scene" aria-label="会议场景">
    <t-alert v-if="errorMessage" theme="error" :message="errorMessage" />
    <t-alert v-if="projection?.statistics.skipped_videos" theme="warning" :message="`本次有 ${projection.statistics.skipped_videos} 个视频暂未纳入，当前展示其余已验证结果。`" />
    <div v-if="loading && !projection" class="meeting-state"><t-loading text="正在读取会议主题簇" /></div>
    <div v-else-if="!projection" class="meeting-state meeting-panel"><t-empty description="尚未生成会议主题簇" /><t-button :loading="generating" @click="refresh">根据当前会议生成</t-button></div>
    <template v-else>
      <div v-if="generating" class="meeting-generation" role="status"><t-loading size="small" /><span>正在刷新会议主题簇（{{ jobProgress }}%），完成前继续展示上一版。</span></div>
      <div class="meeting-overview" aria-label="会议场景概览">
        <article v-for="stat in overviewStats" :key="stat.label" class="meeting-stat"><span>{{ stat.label }}</span><strong>{{ stat.value }}</strong><small>{{ stat.note }}</small></article>
      </div>
      <div class="meeting-result-summary"><span>已分析 <strong>{{ projection.statistics.scanned_videos }}</strong></span><span>符合条件 <strong>{{ projection.statistics.qualified_videos }}</strong></span><span>已跳过 <strong>{{ projection.statistics.skipped_videos }}</strong></span><span>上次生成 <strong>{{ formatGeneratedAt(projection.generated_at) }}</strong></span><t-button size="small" variant="outline" :loading="generating" @click="refresh"><template #icon><RefreshIcon /></template>智能刷新</t-button></div>
      <div v-if="!projection.topic_clusters.length" class="meeting-state meeting-panel"><t-empty description="当前合格会议尚未形成可发布的主题簇" /><t-button variant="outline" :loading="generating" @click="refresh">重新分析</t-button></div>
      <div v-else class="meeting-content">
        <section class="meeting-panel" aria-label="会议主题簇关系"><header class="meeting-panel__head"><strong>会议主题簇</strong><span>{{ projection.topic_clusters.length }} 个主题 · {{ projection.topic_cluster_relations.length }} 条关系</span></header><MeetingTopicGraph :clusters="projection.topic_clusters" :relations="projection.topic_cluster_relations" :selected-id="selectedClusterId" @select="selectCluster" /></section>
        <aside v-if="activeCluster" class="meeting-panel meeting-detail" aria-live="polite">
          <header class="meeting-detail__head"><div><span class="meeting-kicker">{{ activeCluster.business_object || '会议主题' }}</span><h2>{{ activeCluster.title }}</h2></div><span class="meeting-count-pill">{{ activeCluster.source_video_ids.length }} 场会议</span></header>
          <p class="meeting-summary">{{ activeCluster.summary }}</p>
          <nav class="meeting-detail__tabs" role="tablist" aria-label="会议主题详情"><button v-for="tab in detailTabs" :key="tab.id" type="button" role="tab" :aria-selected="activeTab === tab.id" :class="{ 'is-active': activeTab === tab.id }" @click="activeTab = tab.id">{{ tab.label }}<small>{{ tab.count }}</small></button></nav>
          <div class="meeting-detail__body">
            <template v-if="activeTab === 'workItems'"><div class="detail-section-head"><strong>簇内事项分支</strong><span>按当前推进状态归集</span></div><div v-if="activeCluster.work_items.length" class="detail-list"><article v-for="item in activeCluster.work_items" :key="item.work_item_id" class="detail-item"><div class="detail-item__head"><strong>{{ item.title }}</strong><span class="status-label">{{ workItemStatusLabel(item.status) }}</span></div><p v-if="item.current_conclusion">{{ item.current_conclusion }}</p><button v-if="item.evidence_refs.length" type="button" class="evidence-link" @click="openEvidence(item.evidence_refs[0].video_id, item.evidence_refs)"><PlayCircleIcon />查看事项依据</button></article></div><t-empty v-else description="当前主题暂无可发布的事项分支" /></template>
            <template v-else-if="activeTab === 'evolution'"><div class="detail-section-head"><strong>会议演变</strong><span>按会议时间排序</span></div><div v-if="activeCluster.evolution.length" class="evolution-list"><article v-for="event in activeCluster.evolution" :key="event.id" class="evolution-item"><div class="evolution-marker"><span /><time>{{ formatMeetingDate(event.occurred_at) }}</time></div><div class="evolution-content"><strong>{{ event.meeting_title }}</strong><p>{{ event.summary }}</p><div class="evolution-change"><span>关键变化</span><strong>{{ event.change }}</strong></div><button v-if="event.evidence_refs.length" type="button" class="evidence-link" @click="openEvidence(event.video_id, event.evidence_refs)"><PlayCircleIcon />定位原视频</button></div></article></div><t-empty v-else description="当前主题暂无实质演变" /></template>
            <template v-else-if="activeTab === 'decisions'"><div class="detail-section-head"><strong>重要决策</strong><span>{{ activeCluster.decisions.length }} 项</span></div><div v-if="activeCluster.decisions.length" class="detail-list"><article v-for="decision in activeCluster.decisions" :key="decision.id" class="detail-item"><div class="detail-item__head"><strong>{{ decision.text }}</strong><span v-if="decision.status" class="status-label">{{ decisionStatusLabel(decision.status) }}</span></div><button v-if="decision.evidence_refs.length" type="button" class="evidence-link" @click="openEvidence(decision.video_id, decision.evidence_refs)"><PlayCircleIcon />查看决策依据</button></article></div><t-empty v-else description="当前主题尚未形成明确决策" /></template>
            <template v-else-if="activeTab === 'todos'"><div class="detail-section-head"><strong>待办</strong><span>{{ activeCluster.todos.length }} 项</span></div><div v-if="activeCluster.todos.length" class="detail-list"><article v-for="todo in activeCluster.todos" :key="todo.id" class="detail-item"><div class="detail-item__head"><strong>{{ todo.title }}</strong><span class="status-label">{{ todoStatusLabel(todo.status) }}</span></div><p>{{ todo.owner || '负责人未明确' }} · {{ todo.due || '完成时间未明确' }}</p><button v-if="todo.evidence_refs.length" type="button" class="evidence-link" @click="openEvidence(todo.video_id, todo.evidence_refs)"><PlayCircleIcon />定位原视频</button></article></div><t-empty v-else description="当前主题暂无待决策事项或行动项" /></template>
            <template v-else><div class="detail-section-head"><strong>相关知识</strong><span>{{ activeCluster.knowledge.length }} 项</span></div><div v-if="activeCluster.knowledge.length" class="knowledge-list"><button v-for="knowledge in activeCluster.knowledge" :key="knowledge.knowledge_object_id" type="button" class="knowledge-item" @click="emit('selectWiki', { targetPageId: knowledge.wiki_page_id, title: knowledge.title })"><span>{{ knowledgeTypeLabel(knowledge.knowledge_type) }}</span><strong>{{ knowledge.title }}</strong><ChevronRightIcon /></button></div><t-empty v-else description="当前主题暂无通过审核的相关知识" /></template>
          </div>
        </aside>
      </div>
    </template>
  </section>
</template>

<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref } from 'vue'
import { ChevronRightIcon, PlayCircleIcon, RefreshIcon } from 'tdesign-icons-vue-next'
import { fetchCurrentMeetingProjection, fetchMeetingJob, generateMeetingProjection, type MeetingEvidenceRef, type MeetingProjection } from '@/api/videohub/meetingOrchestration'
import MeetingTopicGraph from './MeetingTopicGraph.vue'
type DetailTab = 'workItems' | 'evolution' | 'decisions' | 'todos' | 'knowledge'
const emit = defineEmits<{ selectVideo: [videoId: string, seconds: number]; selectWiki: [target: { targetPageId: string; title: string }] }>()
const projection = ref<MeetingProjection | null>(null); const loading = ref(false); const generating = ref(false); const jobProgress = ref(0); const errorMessage = ref(''); const selectedClusterId = ref(''); const activeTab = ref<DetailTab>('workItems'); let lifecycleVersion = 0
const activeCluster = computed(() => projection.value?.topic_clusters.find(item => item.cluster_id === selectedClusterId.value) || projection.value?.topic_clusters[0] || null)
const overviewStats = computed(() => { const s = projection.value?.statistics; return [{ label: '会议主题簇', value: String(s?.topic_cluster_count || 0), note: '按业务对象归集' }, { label: '会议视频', value: String(s?.qualified_videos || 0), note: '符合当前场景条件' }, { label: '重要决策', value: String(s?.decision_count || 0), note: '均可回到原文' }, { label: '待办', value: String(s?.todo_count || 0), note: '待决策与行动项' }] })
const detailTabs = computed(() => { const c = activeCluster.value; return [{ id: 'workItems' as DetailTab, label: '事项分支', count: c?.work_items.length || 0 }, { id: 'evolution' as DetailTab, label: '演变', count: c?.evolution.length || 0 }, { id: 'decisions' as DetailTab, label: '决策', count: c?.decisions.length || 0 }, { id: 'todos' as DetailTab, label: '待办', count: c?.todos.length || 0 }, { id: 'knowledge' as DetailTab, label: '知识', count: c?.knowledge.length || 0 }] })
function selectCluster(id: string) { selectedClusterId.value = id; activeTab.value = 'workItems' }
function openEvidence(videoId: string, refs: MeetingEvidenceRef[]) { emit('selectVideo', videoId, refs[0] ? refs[0].start_ms / 1000 : 0) }
async function loadCurrent() { const version = lifecycleVersion; loading.value = true; errorMessage.value = ''; try { const next = await fetchCurrentMeetingProjection(); if (version !== lifecycleVersion) return; projection.value = next; if (!next?.topic_clusters.some(item => item.cluster_id === selectedClusterId.value)) selectCluster(next?.topic_clusters[0]?.cluster_id || '') } catch (cause) { if (version === lifecycleVersion) errorMessage.value = errorText(cause, '读取会议主题簇失败') } finally { if (version === lifecycleVersion) loading.value = false } }
async function refresh() { if (generating.value) return; const version = lifecycleVersion; generating.value = true; errorMessage.value = ''; try { let job = await generateMeetingProjection(); jobProgress.value = job.progress; let attempts = 0; while (job.status === 'queued' || job.status === 'running') { if (attempts++ > 120) throw new Error('会议主题簇生成超时，请稍后重试'); await delay(1500); if (version !== lifecycleVersion) return; job = await fetchMeetingJob(job.id); jobProgress.value = job.progress } if (job.status === 'failed') throw new Error(job.error_message || '会议主题簇生成失败'); await loadCurrent() } catch (cause) { if (version === lifecycleVersion) errorMessage.value = errorText(cause, '会议主题簇生成失败') } finally { if (version === lifecycleVersion) generating.value = false } }
function delay(ms: number) { return new Promise(resolve => window.setTimeout(resolve, ms)) }; function errorText(cause: unknown, fallback: string) { return cause instanceof Error ? cause.message : fallback }; function workItemStatusLabel(status: string) { return ({ needs_clarification: '待澄清', proposed: '已有方案', under_review: '评审中', decided: '已决策', in_progress: '执行中', verified: '已验证' } as Record<string, string>)[status] || status || '状态未确认' }; function decisionStatusLabel(status: string) { return ({ active: '当前有效', superseded: '已被替代', rejected: '已否决', pending: '待确认' } as Record<string, string>)[status] || status }; function todoStatusLabel(status: string) { return ({ pending: '待处理', in_progress: '进行中', done: '已完成', cancelled: '已取消', unconfirmed: '后续状态未确认' } as Record<string, string>)[status] || status || '状态未确认' }; function knowledgeTypeLabel(type: string) { return ({ entity: '实体', concept: '概念', case: '案例', methodology: '方法论', insight: '洞察' } as Record<string, string>)[type] || type }; function formatTimestamp(ms: number) { const s = Math.max(0, Math.floor(ms / 1000)); return `${String(Math.floor(s / 60)).padStart(2, '0')}:${String(s % 60).padStart(2, '0')}` }; function formatEvidenceRange(refs: MeetingEvidenceRef[]) { return refs[0] ? `${formatTimestamp(refs[0].start_ms)}-${formatTimestamp(refs[0].end_ms)}` : '' }; function formatMeetingDate(value?: string) { if (!value) return '时间未明确'; const d = new Date(value); return Number.isNaN(d.getTime()) ? '时间未明确' : new Intl.DateTimeFormat('zh-CN', { month: '2-digit', day: '2-digit' }).format(d) }; function formatGeneratedAt(value: string) { const d = new Date(value); return Number.isNaN(d.getTime()) ? '-' : new Intl.DateTimeFormat('zh-CN', { year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', hour12: false }).format(d) }
onMounted(loadCurrent); onBeforeUnmount(() => { lifecycleVersion += 1 }); defineExpose({ refresh })
</script>

<style scoped>
