ont-size-title-large)}.meeting-count-pill,.status-label,.knowledge-type{padding:3px 7px;border-radius:var(--td-radius-round);background:var(--td-bg-color-secondarycontainer);font-size:10px}.meeting-summary{margin:10px 18px;color:var(--td-text-color-secondary);font-size:var(--td-font-size-body-small);line-height:20px}.meeting-detail__tabs{display:flex;gap:18px;min-height:48px;margin-top:14px;padding:0 18px;overflow-x:auto;border-bottom:1px solid var(--td-component-stroke)}.meeting-detail__tabs button{position:relative;display:flex;gap:4px;align-items:center;flex:none;padding:0;border:0;background:transparent;color:var(--td-text-color-secondary);cursor:pointer}.meeting-detail__tabs button.is-active{color:var(--td-brand-color)}.meeting-detail__tabs button.is-active:after{position:absolute;right:0;bottom:-1px;left:0;height:2px;background:var(--td-brand-color);content:''}.meeting-detail__tabs small{color:var(--td-text-color-placeholder);font-size:10px}.meeting-detail__body{padding:15px 18px 20px}.detail-section-head,.detail-item__head{display:flex;justify-content:space-between;gap:10px}.detail-section-head{margin-bottom:9px}.detail-section-head span{color:var(--td-text-color-placeholder);font-size:10px}.detail-list,.knowledge-list{display:grid}.detail-item{display:grid;gap:6px;padding:12px 0;border-top:1px solid var(--td-component-stroke)}.detail-item:first-child{border-top:0}.detail-item strong{overflow-wrap:anywhere;font-size:12px}.detail-item p,.evolution-content p{margin:0;color:var(--td-text-color-secondary);font-size:11px;line-height:18px}.evidence-link{display:inline-flex;align-items:center;gap:4px;padding:0;border:0;background:transparent;color:var(--td-brand-color);cursor:pointer;font-size:10px}.evolution-list{display:grid;gap:12px}.evolution-item{display:grid;grid-template-columns:68px minmax(0,1fr);gap:10px}.evolution-marker{text-align:center;color:var(--td-text-color-placeholder);font-size:10px}.evolution-marker span{display:block;width:12px;height:12px;margin:0 auto 5px;border-radius:var(--td-radius-circle);background:var(--td-brand-color)}.evolution-content{display:grid;gap:7px;padding-bottom:11px;border-bottom:1px solid var(--td-component-stroke)}.evolution-change{display:grid;grid-template-columns:50px minmax(0,1fr);gap:7px;padding:8px 9px;background:var(--td-bg-color-secondarycontainer);font-size:10px}.knowledge-item{display:grid;grid-template-columns:max-content minmax(0,1fr) 15px;gap:8px;align-items:center;padding:11px 0;border:0;border-top:1px solid var(--td-component-stroke);background:transparent;text-align:left;cursor:pointer}.knowledge-item:first-child{border-top:0}.knowledge-item strong{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.knowledge-item :deep(svg){width:14px;color:var(--td-text-color-placeholder)}
@media (max-width:1050px){.meeting-content{grid-template-columns:1fr}}@media (max-width:760px){.meeting-overview{grid-template-columns:repeat(2,minmax(0,1fr))}.meeting-result-summary .t-button{margin-left:0}}@media (max-width:480px){.meeting-overview{grid-template-columns:1fr}.meeting-detail__head{display:grid}}
</style>
